sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-35: FLEET - Validate Check-in (reservation_state changes to COMPLETED)
    var ins = new GlideRecord('x_1850693_enterp_0_inspection');
    ins.addQuery('reservation', current.getUniqueValue());
    ins.addQuery('vehicle', current.getValue('assigned_vehicle'));
    ins.addQuery('inspection_type', 'CHECK_IN');
    ins.setLimit(1);
    ins.query();
    if (!ins.hasNext()) {
        gs.addErrorMessage('A check-in inspection is required to complete the reservation.');
        current.setAbortAction(true);
        return;
    }
    if (!current.check_in_odometer.nil() && !current.check_out_odometer.nil() &&
        parseInt(current.getValue('check_in_odometer'), 10) < parseInt(current.getValue('check_out_odometer'), 10)) {
        gs.addErrorMessage('Check-in odometer cannot be lower than check-out odometer.');
        current.setAbortAction(true);
    }
})(current, previous);
